-- Dedicated disposable DB only. Synthetic schema, no player data.
CREATE SCHEMA IF NOT EXISTS auth;
DO $$ BEGIN IF current_database()<>'idle_hands_test' THEN RAISE EXCEPTION 'isolated database required'; END IF; IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon') THEN CREATE ROLE anon; END IF; IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN CREATE ROLE authenticated; END IF; END $$;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
CREATE TABLE public."birthday_card" ("week_key" text NOT NULL,"signers" jsonb DEFAULT '[]'::jsonb NOT NULL,"pot" float8 DEFAULT 0 NOT NULL,"paid" bool DEFAULT false NOT NULL,"started" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public."catalog" ("key" text NOT NULL,"data" jsonb NOT NULL);
CREATE TABLE public."chair_claims" ("window_id" int8 NOT NULL,"taker" uuid,"name" text,"at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public."code_attempts" ("day" date DEFAULT CURRENT_DATE NOT NULL,"fails" int4 DEFAULT 0 NOT NULL);
CREATE TABLE public."cow_state" ("id" int4 NOT NULL,"week_key" text NOT NULL,"unlock_at" timestamptz NOT NULL,"taken_by" uuid,"taken_at" timestamptz,"orbs" int4,"secs_per_orb" float8,"loot" text,"finished" bool DEFAULT false NOT NULL,"pin_next" timestamptz);
CREATE TABLE public."deeds" ("id" int8 GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"actor" uuid NOT NULL,"target" uuid NOT NULL,"kind" text NOT NULL,"amount" float8 DEFAULT 0 NOT NULL,"hush" bool DEFAULT false NOT NULL,"claimed" bool DEFAULT false NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"detail" text);
CREATE TABLE public."meeting_claims" ("window_id" int8 NOT NULL,"attendee" uuid NOT NULL,"name" text NOT NULL,"joined_at" timestamptz DEFAULT now() NOT NULL,"paid" bool DEFAULT false NOT NULL);
CREATE TABLE public."office_door" ("id" int4 DEFAULT 1 NOT NULL,"code" text DEFAULT 'fixture-only'::text NOT NULL,"max_players" int4 DEFAULT 12 NOT NULL,"open" bool DEFAULT true NOT NULL,"tz" text DEFAULT 'America/New_York'::text NOT NULL,"hire_bonus_pct" float8 DEFAULT 0.5 NOT NULL,"admin" uuid);
CREATE TABLE public."office_play_actions" ("week" text NOT NULL,"actor" uuid NOT NULL,"day" date NOT NULL,"kind" text NOT NULL,"n" int2 DEFAULT 1 NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public."office_play_nominations" ("week" text NOT NULL,"voter" uuid NOT NULL,"category" text NOT NULL,"recipient" uuid NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public."office_play_votes" ("week" text NOT NULL,"voter" uuid NOT NULL,"choice" int2 NOT NULL,"updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public."players" ("id" uuid NOT NULL,"name" text NOT NULL,"avatar_url" text,"pp" float8 DEFAULT 0 NOT NULL,"lifetime" float8 DEFAULT 0 NOT NULL,"cycle" float8 DEFAULT 0 NOT NULL,"owned" jsonb DEFAULT '{}'::jsonb NOT NULL,"upgrades" jsonb DEFAULT '[]'::jsonb NOT NULL,"buffs" jsonb DEFAULT '[]'::jsonb NOT NULL,"equity" int4 DEFAULT 0 NOT NULL,"goodwill" int4 DEFAULT 0 NOT NULL,"notoriety" int4 DEFAULT 0 NOT NULL,"heat" int4 DEFAULT 0 NOT NULL,"raises" int4 DEFAULT 0 NOT NULL,"busted" int4 DEFAULT 0 NOT NULL,"grabs" int4 DEFAULT 0 NOT NULL,"hush" int4 DEFAULT 0 NOT NULL,"quits" int4 DEFAULT 0 NOT NULL,"kind_received" int4 DEFAULT 0 NOT NULL,"tally" jsonb DEFAULT '{}'::jsonb NOT NULL,"hits" jsonb DEFAULT '{}'::jsonb NOT NULL,"achievements" jsonb DEFAULT '[]'::jsonb NOT NULL,"frenzy_until" timestamptz,"last_tick" timestamptz DEFAULT now() NOT NULL,"last_deed" timestamptz,"last_seen" timestamptz DEFAULT now() NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL,"outfit" jsonb,"last_break" timestamptz,"week_pp" float8 DEFAULT 0 NOT NULL,"trophies" int4 DEFAULT 0 NOT NULL,"last_work" timestamptz,"seen_recap" text,"rivalries" int4 DEFAULT 0 NOT NULL,"signed_at" timestamptz,"signature" text,"agreement_version" text,"streak" int4 DEFAULT 0 NOT NULL,"last_checkin" date,"look" jsonb,"dept" text,"perks" jsonb DEFAULT '{}'::jsonb NOT NULL,"today" jsonb DEFAULT '{}'::jsonb NOT NULL,"day_pp" float8 DEFAULT 0 NOT NULL,"contracts" jsonb,"mail" jsonb,"nickname" jsonb,"ooo" text,"last_nick" timestamptz,"last_vend" timestamptz,"vanity" jsonb DEFAULT '{}'::jsonb NOT NULL,"kit" jsonb DEFAULT '{}'::jsonb NOT NULL,"last_restructure" timestamptz,"spent" float8 DEFAULT 0 NOT NULL,"extras" jsonb DEFAULT '[]'::jsonb NOT NULL,"pin" text,"cow" jsonb DEFAULT '[]'::jsonb NOT NULL,"pet" text,"mount" text,"cow_seen" bool DEFAULT false NOT NULL,"wardrobe_owned" jsonb DEFAULT '[]'::jsonb NOT NULL,"cosmetic_styles" jsonb DEFAULT '{}'::jsonb NOT NULL,"cosmetic_equipped" jsonb DEFAULT '{}'::jsonb NOT NULL,"cosmetic_revision" int8 DEFAULT 0 NOT NULL);
CREATE TABLE public."printer_claims" ("window_id" int8 NOT NULL,"fixer" uuid,"name" text,"at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public."season_state" ("id" int4 DEFAULT 1 NOT NULL,"current_week" text DEFAULT to_char(now(), 'IYYY-IW'::text) NOT NULL,"mw" text,"mhit" bool DEFAULT false NOT NULL,"streak" int4 DEFAULT 0 NOT NULL,"best" int4 DEFAULT 0 NOT NULL,"target" float8,"target_week" text);
CREATE TABLE public."seasons" ("week_key" text NOT NULL,"winner" uuid,"winner_name" text,"top" float8,"closed_at" timestamptz DEFAULT now() NOT NULL,"stats" jsonb);
CREATE TABLE public."style_quotes" ("player_id" uuid NOT NULL,"id" uuid DEFAULT gen_random_uuid() NOT NULL,"item" text NOT NULL,"color" text,"design" text NOT NULL,"color_fee" float8 NOT NULL,"design_fee" float8 NOT NULL,"rate" float8 NOT NULL,"revision" int8 NOT NULL,"week" text NOT NULL,"expires_at" timestamptz NOT NULL,"applied" bool DEFAULT false NOT NULL);
CREATE TABLE public."suggestions" ("id" int8 NOT NULL,"author" uuid,"author_name" text,"text" text NOT NULL,"approved" bool DEFAULT false NOT NULL,"created_at" timestamptz DEFAULT now() NOT NULL);
